import itertools
from itertools import combinations
import random

def check_independent_set(edges, n, max_is=2):
    adj = [[False]*n for _ in range(n)]
    for u, v in edges:
        adj[u][v] = True
        adj[v][u] = True
    for subset in combinations(range(n), max_is+1):
        is_independent = True
        for i in range(len(subset)):
            for j in range(i+1, len(subset)):
                if adj[subset[i]][subset[j]]:
                    is_independent = False
                    break
            if not is_independent:
                break
        if is_independent:
            return False
    return True

def check_connectivity(edges, n):
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    def bfs(start, excluded=-1):
        visited = set()
        queue = [start]
        visited.add(start)
        while queue:
            node = queue.pop(0)
            for nb in adj[node]:
                if nb != excluded and nb not in visited:
                    visited.add(nb)
                    queue.append(nb)
        return visited

    reachable = bfs(0)
    if len(reachable) < n:
        return False

    for v in range(n):
        start = 0 if v != 0 else 1
        reachable = bfs(start, excluded=v)
        if len(reachable) < n - 1:
            return False
    return True

